#include <vector>
#include <algorithm>

class Solution {
public:
    int countBalancedSubarrays(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 0) return 0;
        int max_val = *std::max_element(nums.begin(), nums.end());

        std::vector<bool> is_prime(max_val + 1, true);
        if (max_val >= 0) is_prime[0] = false;
        if (max_val >= 1) is_prime[1] = false;
        for (int i = 2; i * i <= max_val; ++i) {
            if (is_prime[i]) {
                for (int j = i * i; j <= max_val; j += i) is_prime[j] = false;
            }
        }

        int ans = 0;
        for (int i = 0; i < n; ++i) {
            std::vector<int> prime_indices;
            int min_gap = 1e9, max_gap = -1e9;
            for (int j = i; j < n; ++j) {
                if (is_prime[nums[j]]) {
                    if (!prime_indices.empty()) {
                        int gap = j - prime_indices.back();
                        min_gap = std::min(min_gap, gap);
                        max_gap = std::max(max_gap, gap);
                    }
                    prime_indices.push_back(j);
                }

                if (prime_indices.size() >= 2) {
                    if (max_gap - min_gap <= k) ans++;
                } else if (prime_indices.size() == 1) {
                    ans++;
                }
            }
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    public int countBalancedSubarrays(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;
        int maxVal = 0;
        for (int x : nums) if (x > maxVal) maxVal = x;

        boolean[] isPrime = new boolean[maxVal + 1];
        Arrays.fill(isPrime, true);
        if (maxVal >= 0) isPrime[0] = false;
        if (maxVal >= 1) isPrime[1] = false;
        for (int i = 2; i * i <= maxVal; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= maxVal; j += i) isPrime[j] = false;
            }
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int lastPrime = -1;
            int countPrimes = 0;
            int minGap = Integer.MAX_VALUE;
            int maxGap = Integer.MIN_VALUE;

            for (int j = i; j < n; j++) {
                if (isPrime[nums[j]]) {
                    if (lastPrime != -1) {
                        int gap = j - lastPrime;
                        minGap = Math.min(minGap, gap);
                        maxGap = Math.max(maxGap, gap);
                    }
                    lastPrime = j;
                    countPrimes++;
                }

                if (countPrimes >= 2) {
                    if (maxGap - minGap <= k) ans++;
                } else if (countPrimes == 1) {
                    ans++;
                }
            }
        }

        return ans;
    }
}

