var countBalancedSubarrays = function(nums, k) {
    const n = nums.length;
    if (n === 0) return 0;
    const maxVal = Math.max(...nums);

    const isPrime = new Uint8Array(maxVal + 1).fill(1);
    if (maxVal >= 0) isPrime[0] = 0;
    if (maxVal >= 1) isPrime[1] = 0;
    for (let i = 2; i * i <= maxVal; i++) {
        if (isPrime[i]) {
            for (let j = i * i; j <= maxVal; j += i) isPrime[j] = 0;
        }
    }

    let ans = 0;
    for (let i = 0; i < n; i++) {
        let lastPrime = -1;
        let countPrimes = 0;
        let minGap = Infinity;
        let maxGap = -Infinity;

        for (let j = i; j < n; j++) {
            if (isPrime[nums[j]]) {
                if (lastPrime !== -1) {
                    const gap = j - lastPrime;
                    if (gap < minGap) minGap = gap;
                    if (gap > maxGap) maxGap = gap;
                }
                lastPrime = j;
                countPrimes++;
            }

            if (countPrimes >= 2) {
                if (maxGap - minGap <= k) ans++;
            } else if (countPrimes === 1) {
                ans++;
            }
        }
    }

    return ans;
};
